mapper.select:
SELECT expert_id, enabled FROM digital_team_project_expert
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY expert_id

SELECT COUNT(*) FROM digital_team_project_expert
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND expert_id = #{expertId}

mapper.update:
UPDATE digital_team_project_expert SET enabled = #{enabled},
updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND expert_id = #{expertId}

mapper.delete:
DELETE FROM digital_team_project_expert
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND expert_id = #{expertId}
